apiVersion: v1
kind: Pod
metadata: {name: millicpu-demo}
spec:
  containers:
    - name: web
      image: nginx:1.28
      resources:
        requests: {cpu: 250m, memory: 64Mi}
        limits: {cpu: 500m, memory: 128Mi}

apiVersion: v1
kind: LimitRange
metadata: {name: container-resources, namespace: demo}
spec:
  limits:
    - type: Container
      default: {memory: 256Mi}
      defaultRequest: {memory: 128Mi}
      min: {memory: 64Mi}
      max: {memory: 512Mi}

variable "demo_token" {
  type      = string
  sensitive = true
  default   = "dummy-not-a-real-token"
}
resource "terraform_data" "demo" {
  input = var.demo_token
}

variable "demo_token" {
  type      = string
  sensitive = true
  default   = "dummy-not-a-real-token"
}
output "token" {
  value     = var.demo_token
  sensitive = true
}

terraform {
  backend "s3" {
    bucket       = "replace-with-your-state-bucket"
    key          = "practice/terraform.tfstate"
    region       = "us-east-1"
    use_lockfile = true
    encrypt      = true
  }
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 6.21.0"
    }
  }
}

terraform {
  required_version = ">= 1.5.0, < 2.0.0"
}

module "network" {
  source = "./modules/network"
}
output "example" {
  value = module.network.subnet_id
}

module "network" {
  source = "./modules/network"
}
output "example" {
  value = module.network.subnet_id
}

variable "environment" {
  type    = string
  default = "dev"
}
locals {
  app_name = "quiz-${var.environment}"
}
output "example" {
  value = local.app_name
}

variable "replicas" {
  type    = number
  default = 3
  validation {
    condition     = var.replicas > 0
    error_message = "replicas must be greater than zero."
  }
}
output "example" {
  value = var.replicas
}

resource "terraform_data" "worker" {
  count = 3
  input = "worker-${count.index}"
}
output "example" {
  value = [for worker in terraform_data.worker : worker.input]
}

resource "terraform_data" "service" {
  for_each = toset(["api", "worker", "api"])
  input    = each.key
}
output "example" {
  value = sort(keys(terraform_data.service))
}

resource "terraform_data" "environment" {
  for_each = { dev = 1, prod = 3 }
  input    = each.value
}
output "example" {
  value = terraform_data.environment["prod"].input
}

resource "terraform_data" "source" {
  input = "example"
}
resource "terraform_data" "consumer" {
  for_each = { api = terraform_data.source.id }
  input    = each.value
}

resource "terraform_data" "service" {
  for_each = toset(["api", "worker"])
  input    = each.key
  # Do not also add count to this block.
}

resource "aws_subnet" "app" {
  vpc_id     = "vpc-0123456789abcdef0"
  cidr_block = "10.0.1.0/24"
}
resource "aws_instance" "web" {
  ami           = "ami-0123456789abcdef0"
  instance_type = "t3.micro"
  subnet_id     = aws_subnet.app.id
}

resource "terraform_data" "service_ready" {
  input = "readiness-marker"
}
resource "terraform_data" "consumer" {
  input      = "no attribute reference to the marker"
  depends_on = [terraform_data.service_ready]
}

resource "terraform_data" "release" {
  input            = "v2"
  triggers_replace = ["v2"]
  lifecycle {
    create_before_destroy = true
  }
}

resource "terraform_data" "important" {
  input = "keep-me"
  lifecycle {
    prevent_destroy = true
  }
}

resource "terraform_data" "shared" {
  input = { owner = "external-controller" }
  lifecycle {
    ignore_changes = [input]
  }
}

resource "terraform_data" "frontend" {
  input = "web"
}
moved {
  from = terraform_data.web
  to   = terraform_data.frontend
}

resource "aws_s3_bucket" "logs" {
  bucket = "existing-demo-logs-bucket"
}
import {
  to = aws_s3_bucket.logs
  id = "existing-demo-logs-bucket"
}

data "aws_ami" "app" {
  most_recent = true
  owners      = ["self"]
  filter {
    name   = "tag:Application"
    values = ["quiz-demo"]
  }
}
output "image_id" {
  value = data.aws_ami.app.id
}

resource "aws_security_group" "web" {
  name   = "quiz-demo-web"
  vpc_id = "vpc-0123456789abcdef0"
  dynamic "ingress" {
    for_each = [80, 443]
    content {
      from_port   = ingress.value
      to_port     = ingress.value
      protocol    = "tcp"
      cidr_blocks = ["10.0.0.0/16"]
    }
  }
}

output "example" {
  value = [for name in ["api", "worker"] : upper(name)]
}

variable "enabled" {
  type    = bool
  default = false
}
output "example" {
  value = var.enabled ? 1 : 0
}

variable "env" {
  type    = string
  default = "test"
}
output "example" {
  value = lookup({ dev = 1, prod = 3 }, var.env, 1)
}

locals {
  settings = jsondecode("{}")
}
output "example" {
  value = try(local.settings.retries, 3)
}

variable "description" {
  type     = string
  default  = null
  nullable = true
}
output "example" {
  value = var.description == null ? "not supplied" : var.description
}

output "example" {
  value = flatten([["a"], ["b", "c"]])
}

output "example" {
  value = merge(
    { team = "app", env = "dev" },
    { team = "platform" }
  )
}

output "example" {
  value = cidrsubnet("10.0.0.0/16", 8, 2)
}

resource "aws_instance" "web" {
  for_each      = toset(["api", "worker"])
  ami           = "ami-0123456789abcdef0"
  instance_type = "t3.micro"
}
output "instance_ids" {
  value = [for item in aws_instance.web : item.id]
}

provider "aws" {
  alias  = "west"
  region = "us-west-2"
}
module "network" {
  source    = "./modules/aws-info"
  providers = { aws = aws.west }
}

resource "terraform_data" "network" {
  input = "network-config"
}
resource "terraform_data" "app" {
  input = terraform_data.network.output
}

